<script setup lang="ts">
import {airports} from '~/data/site'
const route=useRoute();const config=useRuntimeConfig();const email=String(config.public.bookingEmail||'')
const airport=ref(String(route.query.airport||'heathrow'))
const service=ref(String(route.query.service||'arrival'))
const date=ref(String(route.query.date||''))
const passengers=ref(String(route.query.passengers||'1'))
const flight=ref(String(route.query.flight||''))
const name=ref('');const customerEmail=ref('');const notes=ref('');const error=ref('')
function submit(){ if(!email){error.value='Booking email is not configured yet. Set NUXT_PUBLIC_BOOKING_EMAIL in .env before using this demo enquiry flow.';return}error.value='';const subject='UK airport assistance enquiry';const body=`Name: ${name.value}\nEmail: ${customerEmail.value}\nAirport: ${airport.value}\nService: ${service.value}\nTravel date: ${date.value}\nPassengers: ${passengers.value}\nFlight: ${flight.value}\nNotes: ${notes.value}\n\nThis is an enquiry, not a confirmed booking.`; if(import.meta.client)window.location.href=`mailto:${email}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
</script>
<template><div class="interior-page"><SeoSetup title="Request UK Airport VIP Assistance | Enquiry Form" description="Request availability for premium UK airport assistance. No booking is confirmed until the provider accepts the request." path="/book" noindex/><div style="background:#071a2a"><SiteHeader/></div><section class="interior-hero"><div class="shell"><span class="eyebrow">YOUR JOURNEY, YOUR WAY</span><h1>Request airport assistance</h1><p>Share a few details and request availability. This is an enquiry, not an instant confirmed booking.</p></div></section><main class="interior-body shell"><form class="inquiry-form" @submit.prevent="submit"><h2>Your journey details</h2><p>All required fields must be completed before creating an enquiry email.</p><div class="inquiry-fields"><label class="field">Airport<select v-model="airport" required><option v-for="a in airports" :key="a.slug" :value="a.slug">{{a.name}} ({{a.code}})</option></select></label><label class="field">Service<select v-model="service" required><option value="arrival">VIP Arrival</option><option value="departure">VIP Departure</option><option value="transit">VIP Transit</option><option value="fast-track">Fast Track</option><option value="lounge-access">Lounge Access</option><option value="chauffeur-transfers">Chauffeur & Transfers</option></select></label><label class="field">Travel date<input v-model="date" required type="date" :min="new Date().toISOString().slice(0,10)"/></label><label class="field">Passengers<input v-model="passengers" type="number" min="1" max="99" required/></label><label class="field">Flight number<input v-model="flight" placeholder="BA256"/></label><label class="field">Full name<input v-model.trim="name" autocomplete="name" required/></label><label class="field">Your email<input v-model.trim="customerEmail" type="email" autocomplete="email" required/></label><label class="field field-full">Special requests<textarea v-model="notes" placeholder="Travel needs, luggage or mobility details (optional)"/></label></div><p v-if="error" class="validation-notice" role="alert">{{error}}</p><button type="submit" class="btn btn-red">Prepare email enquiry ↗</button><p style="font-size:12px">Demo only: this opens your email application. No payment or booking is processed. Add your verified booking provider API for production.</p></form></main><SiteFooter/></div></template>
